-- Custom migration. Issue #86: foods gain a weight/volume `basis`, one `serving_amount` in the
-- canonical unit of that basis, and nutrition per 100 g / per 100 ml. Per-serving values are derived
-- at read time from now on and are not stored, so `serving_grams`, `kcal_per_serving` and
-- `protein_per_serving` go. `food_log` gains `ml` beside `grams`.
--
-- Hand-written rather than drizzle-kit output because the client ruled (2026-09-15, ruling 1) that
-- the existing rows are test data and are **wiped, not converted**: there is no honest conversion
-- from "87 kcal per serving, serving weight unknown" to "kcal per 100 g". drizzle-kit's table rebuild
-- would carry the old values across column by column, which is exactly what must not happen here.
--
-- `meals` and `meal_items` go with them: `meal_items.food_id` references `foods`, so leaving the rows
-- would dangle, and a saved meal without its items is not a meal. `body_metrics` and `settings` are
-- untouched — they are real data and have nothing to do with this change.
--
-- Deleting the child rows before the DROPs keeps this clean under `PRAGMA foreign_keys = ON`, which
-- is how the app and the tests run; DROP TABLE is an implicit delete of the parent and would
-- otherwise trip the constraint.
--
-- DROP TABLE takes a table's triggers with it, so the two `foods` search_text triggers from 0001 are
-- re-created here, from the same `searchTriggerSql()` renderer (src/db/migrations.test.ts compares
-- them against it). The two `meals` triggers survive: `meals` is emptied, not dropped.
DELETE FROM `meal_items`;
--> statement-breakpoint
DELETE FROM `meals`;
--> statement-breakpoint
DROP TABLE `food_log`;
--> statement-breakpoint
DROP TABLE `foods`;
--> statement-breakpoint
CREATE TABLE `foods` (
	`id` text PRIMARY KEY NOT NULL,
	`updated_at` integer NOT NULL,
	`deleted` integer DEFAULT 0 NOT NULL,
	`name` text NOT NULL,
	`brand` text,
	`basis` text NOT NULL,
	`serving_label` text NOT NULL,
	`serving_amount` real NOT NULL,
	`kcal_per_100` real NOT NULL,
	`protein_per_100` real NOT NULL,
	`archived` integer DEFAULT 0 NOT NULL,
	`use_count` integer DEFAULT 0 NOT NULL,
	`last_used_at` integer,
	`hour_histogram` text,
	`search_text` text DEFAULT '' NOT NULL,
	CONSTRAINT "foods_deleted_check" CHECK("deleted" in (0, 1)),
	CONSTRAINT "foods_archived_check" CHECK("archived" in (0, 1)),
	CONSTRAINT "foods_basis_check" CHECK("basis" in ('weight', 'volume')),
	CONSTRAINT "foods_serving_amount_check" CHECK("serving_amount" > 0),
	CONSTRAINT "foods_kcal_check" CHECK("kcal_per_100" >= 0),
	CONSTRAINT "foods_protein_check" CHECK("protein_per_100" >= 0),
	CONSTRAINT "foods_use_count_check" CHECK("use_count" >= 0)
);
--> statement-breakpoint
CREATE INDEX `foods_use_count_idx` ON `foods` (`use_count`);
--> statement-breakpoint
CREATE INDEX `foods_last_used_at_idx` ON `foods` (`last_used_at`);
